function calculateTax(amount: number) {
  return amount * 0.0825;
}

function totalWithTax(amount: number) {
  return amount + calculateTax(amount);
}

export function isExpired(createdAt: Date) {
  const ms = Date.now() - createdAt.getTime();
  return ms > 86400000;
}

// Version A
export function calculateShipping(weightKg: number) {
  const base = 5;
  const surcharge = weightKg > 20 ? 10 : 0;
  return base + surcharge;
}

// Version B
export const SHIPPING_BASE = 5;
export const SHIPPING_THRESHOLD_KG = 20;
export const SURCHARGE_AMOUNT = 10;
export function calculateShippingV2(weightKg: number) {
  return SHIPPING_BASE + (weightKg > SHIPPING_THRESHOLD_KG ? SURCHARGE_AMOUNT : 0);
}
